"""Validate a reviewed Native intersection packet before left-turn construction.

The packet must be extracted from the selected CARLA/OpenDRIVE map; this module
does not create an intersection by drawing an annotation or inventing a tag.
"""

from math import hypot
from left_turn_measurements import _inside


def _vector(a, b):
    return (b[0] - a[0], b[1] - a[1])


def _unit(v):
    size = hypot(*v)
    if size < 1e-6:
        raise ValueError("route segment has zero length")
    return (v[0] / size, v[1] / size)


def validate(packet):
    required = ("map_sha256", "source_ref", "junction_id", "intersection_polygon",
                "ego_route", "opposing_route", "ego_blueprint_id", "opponent_blueprint_id")
    if any(key not in packet for key in required):
        raise ValueError("original Native map packet incomplete")
    if len(packet["map_sha256"]) != 64 or not packet["source_ref"] or packet["junction_id"] is None:
        raise ValueError("source-hashed original junction required")
    polygon = packet["intersection_polygon"]
    if len(polygon) < 4:
        raise ValueError("intersection polygon requires physical boundary vertices")
    routes = []
    for key in ("ego_route", "opposing_route"):
        route = packet[key]
        if len(route) < 3:
            raise ValueError("connected approach, intersection and exit waypoints required")
        if any(not waypoint.get("source_ref") or waypoint.get("junction_id") != packet["junction_id"]
               and index == 1 for index, waypoint in enumerate(route)):
            raise ValueError("original junction waypoint provenance required")
        if any("x_m" not in point or "y_m" not in point or "road_id" not in point or "lane_id" not in point
               for point in route):
            raise ValueError("original route coordinates and road/lane IDs required")
        coordinates = [(float(p["x_m"]), float(p["y_m"])) for p in route]
        if _inside(coordinates[0], polygon) or not _inside(coordinates[1], polygon) or _inside(coordinates[-1], polygon):
            raise ValueError("route must enter and leave original intersection")
        routes.append(coordinates)
    ego, opposing = routes
    ego_in, ego_out = _unit(_vector(ego[0], ego[1])), _unit(_vector(ego[1], ego[-1]))
    opp_in = _unit(_vector(opposing[0], opposing[1]))
    cross = ego_in[0] * ego_out[1] - ego_in[1] * ego_out[0]
    if cross < 0.35:
        raise ValueError("ego route does not turn left through original junction")
    if ego_in[0] * opp_in[0] + ego_in[1] * opp_in[1] > -0.7:
        raise ValueError("opposing route is not opposite-direction")
    if packet["ego_blueprint_id"] == packet["opponent_blueprint_id"] == "":
        raise ValueError("ordinary vehicle blueprints required")
    return {"map_sha256": packet["map_sha256"], "junction_id": packet["junction_id"],
            "connected_left_turn": True, "opposite_direction": True,
            "physical_realization": "requires Native execution and original frame review"}

"""Deterministic left-turn request policy, separate from measured behavior.

The caller drives this policy once per 20 Hz Native tick using actual body
occupancy and clearance events.  It returns path/speed targets, never a legal
yield conclusion.  A downstream controller must track those targets and retain
the actual controls and body histories.
"""

from dataclasses import dataclass


@dataclass
class TurnPolicy:
    wait_for_initial_opponent: bool
    signal_left: bool
    wait_for_later_opponent: bool | None = None
    phase: str = "approach"

    def tick(self, *, ego_fully_inside, initial_opponent_cleared,
             later_opponent_present, left_route_connected, speed_mps):
        if not left_route_connected:
            raise ValueError("native map has no connected left-turn route")
        if not isinstance(ego_fully_inside, bool) or not isinstance(initial_opponent_cleared, bool):
            raise ValueError("original body occupancy and clearance flags required")
        if speed_mps < 0:
            raise ValueError("speed target must be nonnegative")
        if self.phase == "approach" and ego_fully_inside:
            self.phase = "wait" if self.wait_for_initial_opponent else "turn"
        if self.phase == "wait" and initial_opponent_cleared:
            self.phase = "turn"
        if self.phase == "turn" and self.wait_for_later_opponent and later_opponent_present:
            self.phase = "later_wait"
        if self.phase == "later_wait" and not later_opponent_present:
            self.phase = "turn"
        return {"phase": self.phase, "left_signal_requested": self.signal_left,
                "target_speed_mps": 0.0 if self.phase in ("wait", "later_wait") else float(speed_mps),
                "path_request": "left_turn" if self.phase == "turn" else "approach_or_hold",
                "measured_behavior": None}

"""Source-bound measurements for NRS 484B.253; no legal verdicts.

The caller supplies native body vertices and synchronized control histories.  A
requested controller state or a case name is never substituted for an observed
state.  Intersection boundaries must come from a reviewed map packet.
"""

from math import hypot


def _inside(point, polygon):
    if len(polygon) < 3:
        raise ValueError("intersection polygon needs at least three vertices")
    signs = []
    for start, end in zip(polygon, polygon[1:] + polygon[:1]):
        cross = (end[0] - start[0]) * (point[1] - start[1]) - (end[1] - start[1]) * (point[0] - start[0])
        if abs(cross) > 1e-8:
            signs.append(cross > 0)
    return bool(signs) and all(sign == signs[0] for sign in signs)


def body_occupancy(vertices, polygon):
    if len(vertices) != 8:
        raise ValueError("native vehicle body must have eight world vertices")
    points = [(float(v[0]), float(v[1])) for v in vertices]
    center = (sum(x for x, _ in points) / 8, sum(y for _, y in points) / 8)
    flags = [_inside(point, polygon) for point in points]
    return {"any_vertex_inside": any(flags), "center_inside": _inside(center, polygon), "full_body_inside": all(flags)}


def opposing_approach(ego_heading, other_heading):
    """Geometry diagnostic only; the reviewed road routes establish direction."""
    ex, ey = ego_heading
    ox, oy = other_heading
    en, on = hypot(ex, ey), hypot(ox, oy)
    if en <= 0 or on <= 0:
        raise ValueError("headings must be nonzero")
    return (ex * ox + ey * oy) / (en * on)


def measure(frames, polygon, *, source_id, map_sha256):
    if not source_id or len(map_sha256) != 64 or not frames:
        raise ValueError("original trace and source-hashed map are required")
    result = []
    previous_frame = -1
    for sample in frames:
        required = ("frame", "time_s", "ego_vertices", "opponent_vertices", "ego_heading",
                    "opponent_heading", "ego_speed_mps", "opponent_speed_mps", "ego_signal_left",
                    "ego_turn_committed", "opponent_cleared", "ego_braking")
        missing = [key for key in required if key not in sample]
        if missing:
            raise ValueError("missing original frame fields: " + ", ".join(missing))
        frame = int(sample["frame"])
        if frame <= previous_frame:
            raise ValueError("original frame order must increase")
        previous_frame = frame
        ego = body_occupancy(sample["ego_vertices"], polygon)
        opponent = body_occupancy(sample["opponent_vertices"], polygon)
        result.append({"frame": frame, "time_s": float(sample["time_s"]),
                       "ego": ego, "opponent": opponent,
                       "heading_cosine": opposing_approach(sample["ego_heading"], sample["opponent_heading"]),
                       "ego_speed_mps": float(sample["ego_speed_mps"]),
                       "opponent_speed_mps": float(sample["opponent_speed_mps"]),
                       "ego_signal_left": bool(sample["ego_signal_left"]),
                       "ego_turn_committed": bool(sample["ego_turn_committed"]),
                       "opponent_cleared": bool(sample["opponent_cleared"]),
                       "ego_braking": bool(sample["ego_braking"])})
    if not any(row["ego"]["full_body_inside"] for row in result):
        raise ValueError("no original frame establishes ego fully within intersection")
    return {"source_id": source_id, "map_sha256": map_sha256, "frames": result,
            "legal_judgment": "unresolved"}


def compare(left, right, *, changed_observables):
    """Reject absent or unchanged declared differences; do not infer right-of-way."""
    if left["map_sha256"] != right["map_sha256"]:
        raise ValueError("comparison map differs")
    if left["source_id"] == right["source_id"]:
        raise ValueError("comparison needs distinct original sources")
    if not changed_observables:
        raise ValueError("comparison needs a declared difference")
    first, second = left["frames"], right["frames"]
    if len(first) != len(second) or [r["frame"] for r in first] != [r["frame"] for r in second]:
        raise ValueError("comparison frame windows differ")
    if not any(a[key] != b[key] for key in changed_observables for a, b in zip(first, second)):
        raise ValueError("declared difference absent in original measurements")
    return {"sources": [left["source_id"], right["source_id"]],
            "changed_observables": list(changed_observables), "legal_judgment": "unresolved"}

"""Measure original left-turn traces only after their source bytes are sealed.

This is a saved-only step. It never starts CARLA or infers a legal verdict.
The receipt is an acquisition join, not evidence that a simulated maneuver
actually satisfied the statutory condition or that its pixels were accepted.
"""

import hashlib
import json
from pathlib import Path

from left_turn_measurements import measure
from native_intersection import validate


ASSIGNMENT_ID = "testing__C109749__NRS-484B-253__motor_vehicle_driver"


def _sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def _load(path):
    return json.loads(Path(path).read_text(encoding="utf-8"))


def process(*, case_id, map_path, trace_path, receipt_path):
    """Return measured histories with exact map/trace/receipt source bindings."""
    if not case_id.startswith(ASSIGNMENT_ID + "__"):
        raise ValueError("exact assignment case ID required")
    receipt = _load(receipt_path)
    for key in ("assignment_id", "case_id", "map_sha256", "trace_sha256", "native_map_sha256", "source_id",
                "frame_count", "simulator_frame_rate_hz", "diagnostic_fixture"):
        if key not in receipt:
            raise ValueError("acquisition receipt missing " + key)
    if receipt["assignment_id"] != ASSIGNMENT_ID or receipt["case_id"] != case_id:
        raise ValueError("acquisition receipt identity mismatch")
    if receipt["diagnostic_fixture"]:
        raise ValueError("diagnostic fixture cannot establish delivered original measurement")
    if receipt["simulator_frame_rate_hz"] != 20:
        raise ValueError("original trace must use 20 Hz fixed timestep")
    if _sha(map_path) != receipt["map_sha256"] or _sha(trace_path) != receipt["trace_sha256"]:
        raise ValueError("sealed source bytes changed")
    map_packet = _load(map_path)
    validate(map_packet)
    if map_packet["map_sha256"] != receipt["native_map_sha256"]:
        raise ValueError("Native map identity changed")
    samples = [json.loads(line) for line in Path(trace_path).read_text(encoding="utf-8").splitlines() if line]
    if len(samples) != receipt["frame_count"] or not samples:
        raise ValueError("original trace frame count mismatch")
    for first, second in zip(samples, samples[1:]):
        if second["frame"] != first["frame"] + 1:
            raise ValueError("original trace dropped or duplicated frames")
        if abs((second["time_s"] - first["time_s"]) - 0.05) > 0.002:
            raise ValueError("original trace timestamp cadence differs from 20 Hz")
    if "frame_map_sha256" in receipt:
        frame_map_path = Path(receipt_path).parent / "original-frame-map.json"
        if _sha(frame_map_path) != receipt["frame_map_sha256"]:
            raise ValueError("sealed camera frame map changed")
        frame_map = _load(frame_map_path)
        if frame_map.get("case_id") != case_id or len(frame_map.get("frames", [])) != len(samples):
            raise ValueError("original camera frame map identity/count mismatch")
        for sample, camera_row in zip(samples, frame_map["frames"]):
            if sample["frame"] != camera_row.get("frame") or sample["time_s"] != camera_row.get("time_s"):
                raise ValueError("original camera frame join mismatch")
            cameras = camera_row.get("cameras", {})
            if set(cameras) != {"overview", "approach", "reference_corner", "driver_reference"}:
                raise ValueError("four original cameras required")
            for entry in cameras.values():
                relative = Path(entry["path"])
                if relative.is_absolute() or ".." in relative.parts:
                    raise ValueError("original camera path escapes attempt")
                if _sha(Path(receipt_path).parent / relative) != entry["sha256"]:
                    raise ValueError("sealed original camera bytes changed")
    measured = measure(samples, map_packet["intersection_polygon"],
                       source_id=receipt["source_id"], map_sha256=map_packet["map_sha256"])
    measured.update({"assignment_id": ASSIGNMENT_ID, "case_id": case_id,
                     "source_bindings": {"map_packet_sha256": receipt["map_sha256"],
                                         "original_trace_sha256": receipt["trace_sha256"],
                                         "acquisition_receipt_sha256": _sha(receipt_path)},
                     "physical_acceptance": "unverified", "legal_judgment": "unresolved"})
    return measured

"""Independent full-decode audit of a sealed four-camera Native acquisition.

The audit checks saved source integrity and timing. It cannot establish that a
vehicle or road feature is visible in the pixels or that the law was obeyed.
"""

import argparse
import hashlib
import json
from pathlib import Path

from PIL import Image, UnidentifiedImageError

from saved_left_turn import ASSIGNMENT_ID

CAMERAS = ("overview", "approach", "reference_corner", "driver_reference")


def _sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def audit(attempt, *, case_id, allow_diagnostic=False):
    """Reopen and decode all original pixels, joined to the sealed actor trace."""
    attempt = Path(attempt)
    receipt_path = attempt / "acquisition-receipt.json"
    receipt = json.loads(receipt_path.read_text(encoding="utf-8"))
    if not case_id.startswith(ASSIGNMENT_ID + "__") or (receipt.get("assignment_id"), receipt.get("case_id")) != (ASSIGNMENT_ID, case_id):
        raise ValueError("exact acquisition identity mismatch")
    if receipt.get("diagnostic_fixture") and not allow_diagnostic:
        raise ValueError("diagnostic fixture is not delivery evidence")
    if receipt.get("simulator_frame_rate_hz") != 20 or receipt.get("camera_names") != list(CAMERAS):
        raise ValueError("20 Hz four-camera acquisition required")
    trace_path = attempt / "original-trace.jsonl"
    frame_map_path = attempt / "original-frame-map.json"
    map_path = attempt / "original-map.json"
    for path, key in ((trace_path, "trace_sha256"), (frame_map_path, "frame_map_sha256"), (map_path, "map_sha256")):
        if _sha(path) != receipt.get(key):
            raise ValueError("sealed " + key + " bytes changed")
    trace = [json.loads(line) for line in trace_path.read_text(encoding="utf-8").splitlines() if line]
    frame_map = json.loads(frame_map_path.read_text(encoding="utf-8"))
    if frame_map.get("case_id") != case_id or not isinstance(frame_map.get("frames"), list):
        raise ValueError("camera frame map case mismatch")
    rows = frame_map["frames"]
    if len(trace) != len(rows) or len(rows) != receipt.get("frame_count") or not rows:
        raise ValueError("saved frame count mismatch")
    dimensions = {}
    seen_paths = set()
    previous = None
    for actor, row in zip(trace, rows):
        frame, time_s = actor.get("frame"), actor.get("time_s")
        if not isinstance(frame, int) or not isinstance(time_s, (int, float)) or row.get("frame") != frame or row.get("time_s") != time_s:
            raise ValueError("actor and camera frame/time join mismatch")
        if previous is not None and (frame != previous[0] + 1 or abs(time_s - previous[1] - 0.05) > 0.002):
            raise ValueError("saved frame order or 20 Hz cadence mismatch")
        previous = frame, time_s
        cameras = row.get("cameras")
        if not isinstance(cameras, dict) or set(cameras) != set(CAMERAS):
            raise ValueError("four original cameras required per frame")
        for camera in CAMERAS:
            entry = cameras[camera]
            relative = Path(entry["path"])
            if relative.is_absolute() or ".." in relative.parts or relative.parts[:1] != ("original-frames",):
                raise ValueError("camera source path escapes original frame directory")
            if str(relative) in seen_paths:
                raise ValueError("camera source path reused")
            seen_paths.add(str(relative))
            if relative.name != f"{frame:09d}-{camera}.png":
                raise ValueError("camera source name does not match frame")
            path = attempt / relative
            if not path.is_file() or _sha(path) != entry.get("sha256"):
                raise ValueError("original camera source missing or changed")
            try:
                with Image.open(path) as image:
                    if image.format != "PNG" or image.mode not in ("RGB", "RGBA"):
                        raise ValueError("original camera format is not RGB PNG")
                    image.load()
                    if min(image.size) <= 0:
                        raise ValueError("original camera dimensions invalid")
                    size = tuple(image.size)
            except (UnidentifiedImageError, OSError) as exc:
                raise ValueError("original camera image cannot fully decode") from exc
            if camera in dimensions and dimensions[camera] != size:
                raise ValueError("camera dimensions changed within saved stream")
            dimensions[camera] = size
    return {"assignment_id": ASSIGNMENT_ID, "case_id": case_id,
            "frame_count": len(rows), "decoded_images": len(seen_paths),
            "camera_dimensions": {name: list(dimensions[name]) for name in CAMERAS},
            "source_bindings": {"receipt_sha256": _sha(receipt_path),
                                "trace_sha256": _sha(trace_path),
                                "frame_map_sha256": _sha(frame_map_path)},
            "physical_visibility": "unverified", "legal_judgment": "unresolved"}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--attempt", required=True)
    parser.add_argument("--case", required=True)
    parser.add_argument("--output", required=True)
    parser.add_argument("--allow-diagnostic", action="store_true")
    args = parser.parse_args()
    result = audit(args.attempt, case_id=args.case, allow_diagnostic=args.allow_diagnostic)
    output = Path(args.output)
    output.write_text(json.dumps(result, sort_keys=True, indent=2) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()

"""Exact-case saved measurements for NRS 484B.253.

This describes observed events; it does not decide immediate hazard, yielding,
signal requirements, right-of-way, or any legal outcome.
"""

import argparse
import hashlib
import json
from pathlib import Path

from saved_left_turn import ASSIGNMENT_ID, process


BRANCHES = {
    "inside_yield": (0, "measure_initial_within"),
    "inside_no_yield": (0, "measure_initial_within"),
    "approaching_yield": (1, "measure_approaching"),
    "approaching_no_yield": (1, "measure_approaching"),
    "signal_given": (2, "measure_permission"),
    "signal_omitted": (2, "measure_permission"),
    "reciprocal_yield": (3, "measure_reciprocal"),
    "reciprocal_no_yield": (3, "measure_reciprocal"),
}


def _sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def _first(rows, predicate):
    return next((row["frame"] for row in rows if predicate(row)), None)


def measure_initial_within(rows):
    return {
        "ego_full_body_inside_first_frame": _first(rows, lambda r: r["ego"]["full_body_inside"]),
        "opponent_any_body_inside_first_frame": _first(rows, lambda r: r["opponent"]["any_vertex_inside"]),
        "opponent_full_body_inside_first_frame": _first(rows, lambda r: r["opponent"]["full_body_inside"]),
        "ego_commit_first_frame": _first(rows, lambda r: r["ego_turn_committed"]),
        "opponent_clear_first_frame": _first(rows, lambda r: r["opponent_cleared"]),
        "opposite_heading_cosine_by_frame": [[r["frame"], r["heading_cosine"]] for r in rows],
        "ego_braking_by_frame": [[r["frame"], r["ego_braking"]] for r in rows],
    }


def measure_approaching(rows):
    return {
        "opponent_outside_first_frame": _first(rows, lambda r: not r["opponent"]["any_vertex_inside"]),
        "opponent_inside_first_frame": _first(rows, lambda r: r["opponent"]["any_vertex_inside"]),
        "opponent_speed_mps_by_frame": [[r["frame"], r["opponent_speed_mps"]] for r in rows],
        "ego_commit_first_frame": _first(rows, lambda r: r["ego_turn_committed"]),
        "ego_braking_by_frame": [[r["frame"], r["ego_braking"]] for r in rows],
        "immediate_hazard_judgment": "unresolved",
    }


def measure_permission(rows):
    return {
        "opponent_clear_first_frame": _first(rows, lambda r: r["opponent_cleared"]),
        "ego_commit_first_frame": _first(rows, lambda r: r["ego_turn_committed"]),
        "left_signal_by_frame": [[r["frame"], r["ego_signal_left"]] for r in rows],
        "ego_braking_by_frame": [[r["frame"], r["ego_braking"]] for r in rows],
        "signal_when_and_as_required": "unresolved",
    }


def measure_reciprocal(rows):
    return {
        "initial_opponent_clear_first_frame": _first(rows, lambda r: r["opponent_cleared"]),
        "ego_commit_first_frame": _first(rows, lambda r: r["ego_turn_committed"]),
        "opponent_speed_mps_by_frame": [[r["frame"], r["opponent_speed_mps"]] for r in rows],
        "ego_signal_by_frame": [[r["frame"], r["ego_signal_left"]] for r in rows],
        "later_opponent_identity": "unresolved_without_distinct_source_actor",
    }


METHODS = {name: globals()[name] for _, name in BRANCHES.values()}


def finalize(*, case_id, attempt):
    """Read one sealed acquisition and return a source-bound case observation."""
    if not case_id.startswith(ASSIGNMENT_ID + "__"):
        raise ValueError("exact assignment case ID required")
    suffix = case_id.removeprefix(ASSIGNMENT_ID + "__")
    if suffix not in BRANCHES:
        raise ValueError("case has no selected statutory requirement")
    attempt = Path(attempt)
    map_path = attempt / "original-map.json"
    trace_path = attempt / "original-trace.jsonl"
    receipt_path = attempt / "acquisition-receipt.json"
    for name in ("original-map.json", "original-trace.jsonl", "acquisition-receipt.json"):
        if not (attempt / name).is_file():
            raise ValueError("Missing required source: " + name)
    measured = process(case_id=case_id, map_path=map_path,
                       trace_path=trace_path, receipt_path=receipt_path)
    index, method = BRANCHES[suffix]
    sources = {name: _sha(attempt / name) for name in
               ("original-map.json", "original-trace.jsonl", "acquisition-receipt.json")}
    if (attempt / "original-frame-map.json").is_file():
        sources["original-frame-map.json"] = _sha(attempt / "original-frame-map.json")
    observations = METHODS[method](measured["frames"])
    core_sources = {name: sources[name] for name in
                    ("original-map.json", "original-trace.jsonl", "acquisition-receipt.json")}
    output_key = {0: "initial_within_events", 1: "approaching_events",
                  2: "permission_events", 3: "reciprocal_events"}[index]
    return {"assignment_id": ASSIGNMENT_ID, "case_id": case_id,
            "selected_disposition_index": index, "method": method,
            "source_hashes": sources, "observations": observations,
            "measurements": {output_key: {"method": method, "value": observations,
                                          "sources": core_sources}},
            "original_frame_count": len(measured["frames"]),
            "physical_acceptance": "unverified", "legal_judgment": "unresolved"}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--case")
    parser.add_argument("--attempt", required=True)
    parser.add_argument("--output", required=True)
    args = parser.parse_args()
    case_id = args.case
    if case_id is None:
        receipt = Path(args.attempt) / "acquisition-receipt.json"
        if not receipt.is_file():
            raise ValueError("Missing required source: acquisition-receipt.json")
        case_id = json.loads(receipt.read_text(encoding="utf-8"))["case_id"]
    result = finalize(case_id=case_id, attempt=args.attempt)
    Path(args.output).write_text(json.dumps(result, sort_keys=True, indent=2) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
